const HeaderAds=(()=>{const HOLD_MS=6e3;const SLIDE_MS=600;const STORE_KEY="skiri_header_ads";let timer=null;let paused=false;const strip=()=>document.querySelector(".header-ticker");function isSafeLink(link){return/^https:\/\/[^\s<>"']+$/i.test(link)||/^(index|store|stores|product|categories|recent|help)\.html(\?[^\s<>"']*)?$/i.test(link)}function render(ads){const el=strip();if(!el)return;const list=(ads||[]).filter(a=>a&&a.text&&isSafeLink(String(a.link||"")));if(!list.length)return;el.innerHTML=list.map((a,i)=>{const external=/^https:/i.test(a.link)&&a.link.indexOf(location.origin)!==0;return`<div class="header-ticker-item${i===0?" is-current":""}"><a class="header-ticker-link" href="${escapeHtml(a.link)}"${external?' target="_blank" rel="noopener"':""}>${escapeHtml(a.text)}<span aria-hidden="true"> ›</span></a></div>`}).join("");el.removeAttribute("aria-hidden");el.setAttribute("role","region");el.setAttribute("aria-label","Adverts");syncFocus();restart()}function syncFocus(){const el=strip();el.querySelectorAll(".header-ticker-item").forEach(item=>{const on=item.classList.contains("is-current");item.setAttribute("aria-hidden",String(!on));const a=item.querySelector("a");if(a)a.tabIndex=on?0:-1})}function next(){const el=strip();const items=Array.from(el.querySelectorAll(".header-ticker-item"));if(items.length<2)return;const i=items.findIndex(x=>x.classList.contains("is-current"));const cur=items[i===-1?0:i];const nxt=items[((i===-1?0:i)+1)%items.length];items.forEach(x=>x.classList.remove("is-leaving"));nxt.classList.add("is-ready");void nxt.offsetWidth;nxt.classList.remove("is-ready");cur.classList.remove("is-current");cur.classList.add("is-leaving");nxt.classList.add("is-current");syncFocus()}function tick(){timer=setTimeout(()=>{if(!paused&&!document.hidden)next();tick()},HOLD_MS+SLIDE_MS)}function restart(){clearTimeout(timer);tick()}function init(){const el=strip();if(!el)return;el.classList.add("header-ticker--slide");const first=el.querySelector(".header-ticker-item");if(first&&!el.querySelector(".is-current"))first.classList.add("is-current");el.addEventListener("mouseenter",()=>{paused=true});el.addEventListener("mouseleave",()=>{paused=false});el.addEventListener("focusin",()=>{paused=true});el.addEventListener("focusout",()=>{paused=false});let remembered=null;try{remembered=JSON.parse(localStorage.getItem(STORE_KEY)||"null")}catch(e){remembered=null}if(Array.isArray(remembered)&&remembered.length)render(remembered);else restart();whenIdle(async()=>{const res=await Api.get("getHeaderAds",{});if(!res||!res.ok||!Array.isArray(res.ads))return;try{localStorage.setItem(STORE_KEY,JSON.stringify(res.ads))}catch(e){}if(res.ads.length){if(JSON.stringify(res.ads)!==JSON.stringify(remembered))render(res.ads)}else if(remembered&&remembered.length){restoreDefaults()}})}function restoreDefaults(){const el=strip();el.innerHTML=HEADER_AD_DEFAULTS.map((t,i)=>`<div class="header-ticker-item${i===0?" is-current":""}">${escapeHtml(t)}</div>`).join("");el.setAttribute("aria-hidden","true");el.removeAttribute("role");el.removeAttribute("aria-label");restart()}return{init:init,render:render}})();const HEADER_AD_DEFAULTS=["Local Kiribati sellers","Chat directly with the seller","Delivery, shipping & pickup options"];document.addEventListener("DOMContentLoaded",()=>HeaderAds.init());